h='''    // Container-valued properties (Collections, arrays): type id applies to each element
    @SuppressWarnings("resource")
    private Object _deserializeTyped(JsonParser p2, DeserializationContext ctxt,
            ExtTypedProperty extProp, String typeId) throws JacksonException
    {
        if (!extProp.getProperty().getType().isContainerType()) {
            return extProp._typeDeserializer.deserializeTypedWithKnownTypeId(p2, ctxt, typeId);
        }
        TokenBuffer merged = ctxt.bufferForInputBuffering(p2);
        merged.writeStartArray();
        if (p2.currentToken() == JsonToken.START_ARRAY) {
            while (p2.nextToken() != JsonToken.END_ARRAY) {
                _writeWrapped(merged, p2, typeId);
            }
        } else {
            _writeWrapped(merged, p2, typeId);
        }
        merged.writeEndArray();
        JsonParser mp = merged.asParser(ctxt, p2);
        mp.nextToken();
        return extProp.getProperty().deserialize(mp, ctxt);
    }

    private static void _writeWrapped(TokenBuffer merged, JsonParser p, String typeId)
        throws JacksonException
    {
        merged.writeStartArray();
        merged.writeString(typeId);
        merged.copyCurrentStructure(p);
        merged.writeEndArray();
    }

'''
m="    protected final Object _deserialize(JsonParser p, DeserializationContext ctxt,"
s=s.replace(m,h+m,1)
open(f,'w').write(s)
