package tools.jackson.databind.jsontype.ext;
import java.util.*;
import com.fasterxml.jackson.annotation.*;
import tools.jackson.databind.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
public class TmpSvaTest {
  public static class Foo { public String msg; }
  public static class FooA extends Foo { public String hey; }
  public static class FooB extends Foo { public String whoa; }
  public static class Holder {
    public String footype;
    @JsonTypeInfo(use=JsonTypeInfo.Id.NAME, include=JsonTypeInfo.As.EXTERNAL_PROPERTY, property="footype")
    @JsonSubTypes({@JsonSubTypes.Type(value=FooA.class,name="a"),@JsonSubTypes.Type(value=FooB.class,name="b")})
    @JsonFormat(with=JsonFormat.Feature.ACCEPT_SINGLE_VALUE_AS_ARRAY)
    public List<Foo> foo;
  }
  @Test public void t() throws Exception {
    ObjectMapper m = new ObjectMapper();
    Holder h = m.readValue("{\"footype\":\"a\",\"foo\":{\"msg\":\"x\",\"hey\":\"y\"}}", Holder.class);
    assertEquals(FooA.class, h.foo.get(0).getClass());
    h = m.readValue("{\"foo\":{\"msg\":\"x\",\"hey\":\"y\"},\"footype\":\"a\"}", Holder.class);
    assertEquals(1, h.foo.size());
  }
}
E
